// Stable partition: non-zero front, zeros back
void moveZeroes(vector<int>& a) {
    int w = 0;                                  // write pointer
    for (int v : a) if (v != 0) a[w++] = v;      // compact the non-zero values
    while (w < (int)a.size()) a[w++] = 0;        // fill the tail
}   // O(n) time · O(1) space

