// Rotate right by k using three reversals
void rotateRight(vector<int>& a, long long k) {
    int n = a.size();
    k %= n;                                          // k may exceed n
    reverse(a.begin(), a.end());
    reverse(a.begin(), a.begin() + k);
    reverse(a.begin() + k, a.end());
}   // O(n) time · O(1) space

