// Three reversals instead of k shifts: reverse all, then reverse each part.
static void rev(int *a, int lo, int hi) {
    while (lo < hi) { int t = a[lo]; a[lo++] = a[hi]; a[hi--] = t; }
}

void rotateRight(int *a, int n, int k) {
    if (n == 0) return;
    k %= n;
    if (k < 0) k += n;
    rev(a, 0, n - 1);
    rev(a, 0, k - 1);
    rev(a, k, n - 1);
}   // O(n) time · O(1) space

