// Kadane: best subarray ending here vs starting fresh
long long maxSubarray(const vector<int>& a) {
    long long best = a[0], cur = a[0];
    for (int i = 1; i < (int)a.size(); i++) {
        cur = max((long long)a[i], cur + a[i]);   // extend or restart
        best = max(best, cur);
    }
    return best;
}   // O(n) time · O(1) space

