// Dutch national flag: three regions in one pass
void sortColors(vector<int>& a) {
    int low = 0, mid = 0, high = (int)a.size() - 1;
    while (mid <= high) {
        if (a[mid] == 0)      swap(a[low++], a[mid++]);
        else if (a[mid] == 1) mid++;
        else                  swap(a[mid], a[high--]);   // do NOT advance mid: a[mid] is new
    }
}   // O(n) time · O(1) space

