// Clockwise = transpose, then reverse every row
void rotate(vector<vector<int>>& m) {
    int n = m.size();
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++) swap(m[i][j], m[j][i]);   // upper triangle only
    for (int i = 0; i < n; i++) reverse(m[i].begin(), m[i].end());
}   // O(n^2) time · O(1) extra space

