// Tokenise and rebuild in reverse order
string reverseWords(const string& s) {
    vector<string> words;
    string cur;
    for (int i = 0; i <= (int)s.size(); i++) {
        char c = (i == (int)s.size()) ? ' ' : s[i];
        if (c == ' ') { if (!cur.empty()) { words.push_back(cur); cur.clear(); } }
        else cur += c;
    }
    string out;
    for (int k = (int)words.size() - 1; k >= 0; k--) {
        if (!out.empty()) out += ' ';
        out += words[k];
    }
    return out;
}   // O(n) time · O(n) space

