// Cyclic sort: value v belongs at index v - 1
int firstMissingPositive(vector<int>& a) {
    int n = a.size();
    for (int i = 0; i < n; i++)
        while (a[i] > 0 && a[i] <= n && a[a[i] - 1] != a[i])   // in range, not home yet
            swap(a[i], a[a[i] - 1]);
    for (int i = 0; i < n; i++)
        if (a[i] != i + 1) return i + 1;                        // first hole
    return n + 1;                                               // all of 1..n present
}   // O(n) time · O(1) space

