def majority_element_ii(a):
    c1 = c2 = 0
    v1 = v2 = None
    for x in a:                       # Boyer-Moore with two slots
        if c1 > 0 and x == v1:
            c1 += 1
        elif c2 > 0 and x == v2:
            c2 += 1
        elif c1 == 0:
            v1, c1 = x, 1
        elif c2 == 0:
            v2, c2 = x, 1
        else:
            c1 -= 1
            c2 -= 1
    need = len(a) // 3
    out = []
    for cand in (v1, v2):             # verify: existence is not guaranteed here
        if cand is not None and a.count(cand) > need and cand not in out:
            out.append(cand)
    return out
# O(n) time · O(1) space

