    while (i >= 0 && a[i] >= a[i + 1]) i--;               // pivot: last index that can grow
    if (i >= 0) {
        int j = n - 1;
        while (a[j] <= a[i]) j--;
        int t = a[i]; a[i] = a[j]; a[j] = t;
