    cnt[0] = 1;                              // the empty prefix
    long sum = 0, ans = 0;
    for (int v : a) {
        sum += v;
        int r = Math.floorMod((int) sum, k);  // normalise negatives
        ans += cnt[r];                       // every earlier equal remainder forms a valid subarray
        cnt[r]++;
    }
