// Fill from the back: the biggest square is at one of the two ends
vector<int> sortedSquares(const vector<int>& a) {
    int n = a.size();
    vector<int> out(n);
    int i = 0, j = n - 1;
    for (int k = n - 1; k >= 0; k--) {
        long long li = (long long)a[i] * a[i], rj = (long long)a[j] * a[j];
        if (li > rj) { out[k] = (int)li; i++; }
        else         { out[k] = (int)rj; j--; }
    }
    return out;
}   // O(n) time · O(n) space

