// Track the closest sum instead of an exact match
int threeSumClosest(vector<int> a, int target) {
    sort(a.begin(), a.end());
    int n = a.size();
    long long best = (long long)a[0] + a[1] + a[2];
    for (int i = 0; i + 2 < n; i++) {
        int l = i + 1, r = n - 1;
        while (l < r) {
            long long s = (long long)a[i] + a[l] + a[r];
            if (llabs(s - target) < llabs(best - target)) best = s;
            if (s < target) l++;
            else if (s > target) r--;
            else return (int)s;                     // exact hit: nothing can be closer
        }
    }
    return (int)best;
}   // O(n^2) time · O(1) space

