// Sliding counts; `diff` counts buckets that still disagree
vector<int> findAnagrams(const string& s, const string& p) {
    vector<int> out;
    int n = s.size(), m = p.size();
    if (m > n) return out;
    vector<int> cnt(26, 0);
    for (char c : p) cnt[c - 'a']++;
    int diff = 0;
    for (int c = 0; c < 26; c++) if (cnt[c] != 0) diff++;      // buckets that need fixing
    for (int i = 0; i < n; i++) {
        int in = s[i] - 'a';
        if (cnt[in] == 0) diff++;                              // this bucket becomes wrong
        cnt[in]--;
        if (cnt[in] == 0) diff--;                              // ... and this one becomes right
        if (i >= m) {
            int out = s[i - m] - 'a';
            if (cnt[out] == 0) diff++;
            cnt[out]++;
            if (cnt[out] == 0) diff--;
        }
        if (diff == 0) out.push_back(i - m + 1);
    }
    return out;
}   // O(n) time · O(1) space

