from collections import Counter

def find_anagrams(s, p):
    m = len(p)
    if m > len(s):
        return []
    need = Counter(p)
    win = Counter(s[:m])
    out = []
    if win == need:
        out.append(0)
    for i in range(m, len(s)):
        win[s[i]] += 1
        left = s[i - m]
        win[left] -= 1
        if win[left] == 0:
            del win[left]
        if win == need:
            out.append(i - m + 1)
    return out
# O(n) time · O(1) space

