    long prod = 1, count = 0;
    int left = 0;
    for (int right = 0; right < a.length; right++) {
        prod *= a[right];
        while (prod >= k && left <= right) prod /= a[left++];   // shrink until valid
        count += right - left + 1;                              // all subarrays ending at `right`
    }
    return count;
}   // O(n) time · O(1) space

