int numSubarrayProductLessThanK(const int *a, int n, int k) {
    if (k <= 1) return 0;
    long long prod = 1;
    int left = 0, count = 0;
    for (int right = 0; right < n; right++) {
        prod *= a[right];
        while (prod >= k) prod /= a[left++];
        count += right - left + 1;                        // windows ending at `right`
    }
    return count;
}   // O(n) time · O(1) space

