// Two indices over sorted arrays: equal → record and advance both, else advance the smaller.
int intersectSorted(const int *a, int n, const int *b, int m, int *out) {
    int i = 0, j = 0, k = 0;
    while (i < n && j < m) {
        if (a[i] == b[j]) { out[k++] = a[i]; i++; j++; }
        else if (a[i] < b[j]) i++;
        else j++;
    }
    return k;
}   // O(n + m) time · O(1) space

