from collections import deque

def max_sliding_window(a, k):
    dq = deque()          # indices, values decreasing from the left
    out = []
    for i, v in enumerate(a):
        while dq and a[dq[-1]] <= v:
            dq.pop()                       # dominated: never the maximum again
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()                   # expired
        if i >= k - 1:
            out.append(a[dq[0]])
    return out
# O(n) time · O(k) space

