            long long lv = left[i], rv = right[j];
            long long ci = 0, cj = 0;
            while (i < k && left[i] == lv) { ci++; i++; }
            while (j >= 0 && right[j] == rv) { cj++; j--; }
            total += ci * cj;
        } else if (sum < 0) i++;
        else j--;
    }
    free(left); free(right);
    return (int) total;
}   // O(n^2 log n) time · O(n^2) space

