// Sign of a[|v|-1] is the "seen" flag — no extra memory
vector<int> findDuplicates(vector<int>& a) {
    vector<int> out;
    for (int v : a) {
        int i = abs(v) - 1;
        if (a[i] < 0) out.push_back(abs(v));      // second visit
        else a[i] = -a[i];                        // first visit: mark
    }
    for (int& v : a) v = abs(v);                  // restore the input
    return out;
}   // O(n) time · O(1) space

