// +1 for 1, -1 for 0: equal counts = zero balance
int findMaxLength(vector<int>& a) {
    unordered_map<int, int> first{{0, -1}};       // balance -> earliest index
    int bal = 0, best = 0;
    for (int i = 0; i < (int)a.size(); i++) {
