// exactly(k) = atMost(k) - atMost(k - 1), counted with a sliding window.
static int atMost(const int *a, int n, int k) {
    if (k < 0) return 0;
    int count[20001] = {0}, used = 0, left = 0, total = 0;
    for (int right = 0; right < n; right++) {
        int v = a[right] + 10000;
        if (count[v]++ == 0) used++;
        while (used > k) {
            int u = a[left++] + 10000;
            if (--count[u] == 0) used--;
        }
        total += right - left + 1;
    }
    return total;
}

