// Group by remainder mod k: pairs of remainders (r, k - r) count for free.
int countPairsDivisibleByK(const int *a, int n, int k) {
    int *count = calloc((size_t) k, sizeof(int));
    long long total = 0;
    for (int i = 0; i < n; i++) {
        int r = ((a[i] % k) + k) % k;
        int want = r ? k - r : 0;
        total += count[want];
        count[r]++;
    }
    free(count);
    return (int) total;
}   // O(n) time · O(k) space

