// For each ordered pair (a, b): Kadane that must include a b
int largestVariance(string s) {
    int best = 0;
    for (char a = 'a'; a <= 'z'; a++)
        for (char b = 'a'; b <= 'z'; b++) {
            if (a == b) continue;
            int withB = 0, noB = 0;                 // running sums of each state
            bool seenB = false;
            for (char c : s) {
                if (c == a) { withB++; noB++; }
                else if (c == b) {
                    withB = max(seenB ? withB - 1 : INT_MIN, noB - 1);   // start or extend
                    noB = 0;
                    seenB = true;
                }
                if (seenB) best = max(best, withB);
            }
        }
    return best;
}   // O(26² · n) time · O(1) space

