def eval_rpn(tokens):
    st = []
    ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b,
           '*': lambda a, b: a * b,
           '/': lambda a, b: int(a / b)}    # truncate toward zero, not floor
    for t in tokens:
        if t in ops:
            b = st.pop()                     # right operand first
            a = st.pop()
            st.append(ops[t](a, b))
        else:
            st.append(int(t))
    return st[-1]

