public:
    MyCircularQueue(int k) : buf(k) {}
    bool enQueue(int v) {
        if (sz == (int)buf.size()) return false;
        buf[(head + sz) % buf.size()] = v;           // wrap with modulo
        sz++;
        return true;
    }
    bool deQueue() {
        if (sz == 0) return false;
        head = (head + 1) % buf.size(); sz--;
        return true;
    }
