// Each rise needs a new layer; each fall ends layers for free
int minNumberOperations(vector<int>& target) {
    long long ops = 0;
    int prev = 0;
    for (int v : target) {
        if (v > prev) ops += v - prev;           // start (v - prev) new operations
        prev = v;                                // falls cost nothing
    }
    return (int)ops;
}   // O(n) time · O(1) space

