// Greedy feasibility pass, then binary search the capacity
int shipWithinDays(vector<int>& w, int days) {
    auto fits = [&](int cap) {
        int used = 1, load = 0;
        for (int x : w) {
            if (load + x > cap) { used++; load = 0; }   // start a new day
            load += x;
        }
        return used <= days;
    };
    int lo = *max_element(w.begin(), w.end());          // lower bound
    int hi = accumulate(w.begin(), w.end(), 0);         // upper bound
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (fits(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}   // O(n log total) time · O(1) space

