// Sort, then binary search d and two-pointer count pairs within d
int smallestDistancePair(vector<int>& a, int k) {
    sort(a.begin(), a.end());
    int n = a.size(), lo = 0, hi = a.back() - a.front();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long cnt = 0;
        for (int i = 0, j = 0; i < n; i++) {
            while (a[i] - a[j] > mid) j++;        // shrink the window
            cnt += i - j;                         // pairs ending at i, within mid
        }
        if (cnt >= k) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}   // O(n log n + n log maxDist) time · O(1) space

