    int *dp = calloc((size_t) k + 1, sizeof(int));
    int moves = 0;
    while (dp[k] < n) {
        moves++;
        for (int e = k; e >= 1; e--)
            dp[e] = dp[e] + dp[e - 1] + 1;
    }
    free(dp);
    return moves;
