    struct ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return 1;                       // true
    }
    return 0;                                             // false
}   // O(n) time · O(1) space

