struct TreeNode { int val; TreeNode *left, *right; TreeNode(int v = 0) : val(v), left(nullptr), right(nullptr) {} };
vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
    vector<vector<int>> out;
