def serialize(root):
    parts = []
    def enc(node):
        if not node:
            parts.append('#')          # explicit null marker
            return
        parts.append(str(node.val))
        enc(node.left)
        enc(node.right)

    enc(root)
    return ','.join(parts)

def deserialize(data):
    tokens = iter(data.split(','))
    def dec():
        tok = next(tokens)
        if tok == '#':
            return None
        node = TreeNode(int(tok))
        node.left = dec()              # the next token starts the left subtree
        node.right = dec()
        return node

    return dec()

