from collections import deque

def closest_k_values(root, target, k):
    win = deque()                    # ascending values, size at most k
    def walk(node):
        if not node:
            return
        walk(node.left)
        win.append(node.val)
        if len(win) > k:             # drop the candidate farthest from target
            if abs(win[0] - target) <= abs(win[-1] - target):
                win.pop()
            else:
                win.popleft()
        walk(node.right)

    walk(root)
    return list(win)

