def find_circle_num(is_connected):
    n = len(is_connected)
    seen = [False] * n
    provinces = 0
    for start in range(n):
        if seen[start]:
            continue
        provinces += 1                # a new province begins here
        stack = [start]
        seen[start] = True
        while stack:
            u = stack.pop()
            for v in range(n):
                if is_connected[u][v] and not seen[v]:
                    seen[v] = True
                    stack.append(v)
    return provinces

