        for (int[] e : adj.get(u)) {
            int v = e[0], id = e[1];
            if (id == parentEdge) continue;      // skip the edge we came from
            if (disc[v] != 0) low[u] = Math.min(low[u], disc[v]);   // back edge
            else {
                dfs(v, id);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > disc[u]) bridges.add(Arrays.asList(u, v));   // bridge
            }
        }
    }
