        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < conn.size(); i++) {      // give every edge an id
            int a = conn.get(i).get(0), b = conn.get(i).get(1);
            adj.get(a).add(new int[]{b, i});
            adj.get(b).add(new int[]{a, i});
