        disc = new int[n]; low = new int[n];
        bridges.clear(); timer = 0;
        for (int u = 0; u < n; u++) if (disc[u] == 0) dfs(u, -1);
        return bridges;
    }
}   // O(n + m) time · O(n + m) space

