// Dijkstra with a path count: replace on improvement, add on a tie
int countPaths(int n, vector<vector<int>>& roads) {
    const long long MOD = 1000000007;
    vector<vector<pair<int,int>>> adj(n);        // u -> (v, time)
    for (auto& r : roads) {
        adj[r[0]].push_back({r[1], r[2]});
        adj[r[1]].push_back({r[0], r[2]});
    }
    vector<long long> dist(n, LLONG_MAX), ways(n, 0);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    dist[0] = 0; ways[0] = 1;
    pq.push({0, 0});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;               // stale entry
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {               // shorter: replace the count
                dist[v] = d + w;
                ways[v] = ways[u];
                pq.push({dist[v], v});
            } else if (d + w == dist[v]) {       // equal: add the count
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }
    return (int)ways[n - 1];
}   // O(m log n) time · O(n + m) space

