// The window is three wide instead of two
int tribonacci(int n) {
    if (n < 2) return n;                         // T0 = 0, T1 = 1
    int a = 0, b = 1, c = 1;                     // T0, T1, T2
    for (int i = 3; i <= n; i++) {
