// One row is enough: dp[j] holds the cell above until it is overwritten
int uniquePaths(int m, int n) {
    vector<int> dp(n, 1);                        // top row: one route along it
    for (int i = 1; i < m; i++)
        for (int j = 1; j < n; j++)
            dp[j] += dp[j - 1];                  // from above + from the left
    return dp[n - 1];
}   // O(m · n) time · O(n) space

