    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i-1] == text2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1        # extend the match
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])   # drop one character
    return dp[m][n]

