def find_number_of_lis(nums):
    n = len(nums)
    dp = [1] * n                 # longest chain ending at i
    cnt = [1] * n                # how many chains of that length end at i
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    cnt[i] = cnt[j]          # a strictly longer chain: replace
                elif dp[j] + 1 == dp[i]:
                    cnt[i] += cnt[j]         # same length: add the routes
    best = max(dp)
    return sum(c for length, c in zip(dp, cnt) if length == best)

code.c:
// Keep both the best length ending at i and how many ways reach it.
int findNumberOfLIS(const int *a, int n) {
    int *len = malloc(sizeof(int) * (size_t) n), *count = malloc(sizeof(int) * (size_t) n);
    int bestLen = 1;
    for (int i = 0; i < n; i++) { len[i] = 1; count[i] = 1; }
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (a[j] >= a[i]) continue;
            if (len[j] + 1 > len[i]) { len[i] = len[j] + 1; count[i] = count[j]; }
            else if (len[j] + 1 == len[i]) count[i] += count[j];   // another way to the same length
        }
        if (len[i] > bestLen) bestLen = len[i];
    }
    long long total = 0;
    for (int i = 0; i < n; i++) if (len[i] == bestLen) total += count[i];
    free(len); free(count);
    return (int) total;
}   // O(n^2) time · O(n) space

