int jump(const int *nums, int n) {
    int jumps = 0, currentEnd = 0, farthest = 0;
    for (int i = 0; i < n - 1; i++) {
        if (i + nums[i] > farthest) farthest = i + nums[i];
        if (i == currentEnd) {                             // the layer is exhausted: jump
            jumps++;
            currentEnd = farthest;
        }
    }
    return jumps;
}   // O(n) time · O(1) space

