    if (!n) return 0;
    qsort(intervals, (size_t) n, sizeof(int *), cmpEnd);
    int removed = 0, lastEnd = intervals[0][1];
    for (int i = 1; i < n; i++) {
        if (intervals[i][0] < lastEnd) removed++;          // overlaps: drop it
        else lastEnd = intervals[i][1];
    }
    return removed;
}   // O(n log n) time · O(1) space

