    int points_0[] = {10, 16};
    int points_1[] = {2, 8};
    int points_2[] = {1, 6};
    int points_3[] = {7, 12};
    int *points[] = {points_0, points_1, points_2, points_3};
    int n = 4;
    printf("%lld\n", (long long) findMinArrowShots(points, n));
    return 0;
}

