    char *out = malloc(4096);
    int n = 0;
    int counts[3] = {a, b, c};
    while (1) {
        int pick = -1;
        for (int i = 0; i < 3; i++) {
            if (!counts[i]) continue;
            int repeats = n >= 2 && out[n - 1] == 'a' + i && out[n - 2] == 'a' + i;
            if (repeats) continue;                         // would be three in a row
            if (pick < 0 || counts[i] > counts[pick]) pick = i;
        }
        if (pick < 0) break;
        out[n++] = (char) ('a' + pick);
        counts[pick]--;
    }
    out[n] = '\0';
    return out;
}   // O(a + b + c) time · O(a + b + c) space

