    int heights[] = {4, 2, 7, 6, 9, 14, 12};
    int n = 7;
    int bricks = 5;
    int ladders = 1;
    printf("%lld\n", (long long) furthestBuilding(heights, n, bricks, ladders));
    return 0;
}

