        out.add(Arrays.asList(a[i], b[j]));
        if (j + 1 < b.length)                        // the successor in this row
            pq.add(new long[]{(long) a[i] + b[j+1], i, j + 1});
    }
    return out;
}   // O(k log min(k, n)) time · O(min(k, n)) space

