// 26 child slots per node plus one "a word ends here" flag
class Trie {
public:
    struct Node {
        Node* kids[26] = {};
        bool ends = false;
    };
    Node* root = new Node();
    void insert(string word) {
        Node* cur = root;
        for (char c : word) {
            int i = c - 'a';
            if (!cur->kids[i]) cur->kids[i] = new Node();
            cur = cur->kids[i];
        }
        cur->ends = true;                        // a word stops here
    }
    bool search(string word) {
        Node* cur = walk(word);
        return cur && cur->ends;                 // ... and only here
    }
    bool startsWith(string prefix) {
        return walk(prefix) != nullptr;          // any node on the path will do
    }
private:
    Node* walk(const string& s) {
        Node* cur = root;
        for (char c : s) {
            cur = cur->kids[c - 'a'];
            if (!cur) return nullptr;
        }
        return cur;
    }
};   // O(L) per operation · O(total characters) space

