    for (const string& w : words) {
        int at = -1;
        bool ok = true;
        for (char c : w) {
            const vector<int>& list = pos[c - 'a'];
            auto it = upper_bound(list.begin(), list.end(), at);   // next occurrence
            if (it == list.end()) { ok = false; break; }
            at = *it;
        }
        if (ok) count++;
    }
    return count;
}   // O(|s| + total word length · log |s|) time · O(|s|) space

