int numMatchingSubseq(const char *s, char **words, int n) {
    int matched = 0;
    for (int i = 0; i < n; i++) {
        int j = 0;
        for (int k = 0; s[k] && words[i][j]; k++)
            if (s[k] == words[i][j]) j++;                   // consume the next needed letter
        if (!words[i][j]) matched++;
    }
    return matched;
}   // O(n * length) time · O(1) space

