            if (nxt == null) {
                kids.add(new HashMap<>());
                ends.add(null);
                nxt = kids.size() - 1;
                kids.get(cur).put(c, nxt);
            }
            cur = nxt;
        }
        ends.set(cur, w);
    }
    List<String> found = new ArrayList<>();
    for (int r = 0; r < board.length; r++)
        for (int c = 0; c < board[0].length; c++)
            dfs(board, r, c, 0, kids, ends, found);
    return found;
}
