int longestDecomposition(String text) {
    int left = 0, right = text.length(), parts = 0;
    while (left < right) {
        int size = 1;
        boolean matched = false;
        while (left + size <= right - size) {
            String a = text.substring(left, left + size);
            String b = text.substring(right - size, right);
            if (a.equals(b)) {
