// Longest palindromic prefix via KMP on s + '#' + reverse(s)
string shortestPalindrome(string s) {
    if (s.empty()) return "";
    string rev(s.rbegin(), s.rend());
    string comb = s + "#" + rev;
    int n = comb.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
