// Each character contributes (i - prev) * (next - i) substrings
int uniqueLetterString(string s) {
    const int MOD = 1e9 + 7;
    int n = s.size();
    vector<int> nxt(n, n), lastPos(26, n);
    for (int i = n - 1; i >= 0; i--) {
        nxt[i] = lastPos[s[i] - 'A'];            // next occurrence of the same letter
        lastPos[s[i] - 'A'] = i;
    }
    vector<int> prevPos(26, -1);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        int prev = prevPos[s[i] - 'A'];
        prevPos[s[i] - 'A'] = i;
        total = (total + (long long)(i - prev) * (nxt[i] - i)) % MOD;
    }
    return (int) total;
}   // O(n) time · O(n) space

