def unique_letter_string(s):
    MOD = 10**9 + 7
    n = len(s)
    nxt = [n] * n                            # next occurrence of the same letter
    last = {}
    for i in range(n - 1, -1, -1):
        nxt[i] = last.get(s[i], n)
        last[s[i]] = i
    prev = {}
    total = 0
    for i, ch in enumerate(s):
        p = prev.get(ch, -1)
        prev[ch] = i
        total += (i - p) * (nxt[i] - i)       # substrings where this ch is unique
    return total % MOD

