def distinct_echo_substrings(text):
    M1, M2, B1, B2 = 10**9 + 7, 10**9 + 9, 131, 137
    n = len(text)
    h1 = [0] * (n + 1); h2 = [0] * (n + 1)
    p1 = [1] * (n + 1); p2 = [1] * (n + 1)
    for i, ch in enumerate(text):
        v = ord(ch)
        h1[i+1] = (h1[i] * B1 + v) % M1
        h2[i+1] = (h2[i] * B2 + v) % M2
        p1[i+1] = p1[i] * B1 % M1
        p2[i+1] = p2[i] * B2 % M2

    def digest(l, r):                  # hash of text[l:r], both moduli
        a = (h1[r] - h1[l] * p1[r-l]) % M1
        b = (h2[r] - h2[l] * p2[r-l]) % M2
        return (a, b)

    seen = set()
    for i in range(n):
        for j in range(i + 1, n):
            k = j + (j - i)            # end of the second half
            if k > n:
                break
            if digest(i, j) == digest(j, k):
                seen.add((j - i, digest(i, j)))    # distinct by content
    return len(seen)

