            return memo[i]                 # computed once per start index
        if i == n:
            return ['']
        out = []
        for j in range(i + 1, n + 1):
            piece = s[i:j]
            if piece in words:
                for rest in solve(j):
                    out.append(piece + (' ' + rest if rest else ''))
        memo[i] = out
        return out

