// The definition is recursive; the table removes all repeated work
int fib(int n) {
    if (n < 2) return n;
    vector<int> memo(n + 1, -1);
    memo[0] = 0; memo[1] = 1;
    function<int(int)> go = [&](int x) {
        if (memo[x] != -1) return memo[x];   // computed before
        return memo[x] = go(x - 1) + go(x - 2);
    };
    return go(n);
}   // O(n) time · O(n) space

