vector<vector<string>> partition(string s) {
    vector<vector<string>> out;
    vector<string> cur;
    function<bool(int,int)> isPal = [&](int i, int j) {
        while (i < j) {
            if (s[i] != s[j]) return false;
            i++; j--;
        }
        return true;
    };
    function<void(int)> dfs = [&](int start) {
