def max_score_words(words, letters, score):
    have = [0] * 26
    for ch in letters:
        have[ord(ch) - 97] += 1

    need = []
    worth = []
    for w in words:
        counts = [0] * 26
        total = 0
        for ch in w:
            counts[ord(ch) - 97] += 1
            total += score[ord(ch) - 97]
        need.append(counts)
        worth.append(total)

    suffix = [0] * (len(words) + 1)          # best possible still ahead
    for i in range(len(words) - 1, -1, -1):
        suffix[i] = suffix[i + 1] + worth[i]

    best = 0

    def dfs(i, got):
        nonlocal best
        if got + suffix[i] <= best:
            return                           # cannot beat the best any more
        if i == len(words):
            best = max(best, got)
            return
        if all(need[i][c] <= have[c] for c in range(26)):
            for c in range(26):
                have[c] -= need[i][c]        # spend the letters
            dfs(i + 1, got + worth[i])
            for c in range(26):
                have[c] += need[i][c]        # give them back
        dfs(i + 1, got)                      # skip the word

    dfs(0, 0)
    return best

