// Each bit position is counted modulo three
int singleNumber(vector<int>& nums) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int ones = 0;
        for (int x : nums) ones += (x >> i) & 1;   // how many numbers have bit i
        if (ones % 3) result |= 1 << i;            // only the single value does
    }
    return result;
}   // O(32 · n) time · O(1) space

