// Count each bit modulo 3 with two accumulators — the standard bit-trick circuit.
int singleNumberII(const int *nums, int n) {
    unsigned ones = 0, twos = 0;
    for (int i = 0; i < n; i++) {
        ones = (ones ^ (unsigned) nums[i]) & ~twos;
        twos = (twos ^ (unsigned) nums[i]) & ~ones;
    }
    return (int) ones;
}   // O(n) time · O(1) space

