// Shift both ends until they agree: what is left is the common prefix
int rangeBitwiseAnd(int left, int right) {
    int shift = 0;
    while (left < right) {
        left >>= 1;
        right >>= 1;
        shift++;                             // one more bit is known to differ
    }
    return left << shift;                    // the shared high bits
}   // O(32) time · O(1) space

