// Columns are independent: cost each one, then add up
int minFlips(int a, int b, int c) {
    int flips = 0;
    for (int i = 0; i < 32; i++) {
        int x = (a >> i) & 1, y = (b >> i) & 1, z = (c >> i) & 1;
        if (z == 0) flips += x + y;          // both must be cleared
        else if (x + y == 0) flips += 1;     // at least one must be set
    }
    return flips;
}   // O(32) time · O(1) space

