int minFlips(int a, int b, int c) {
    int flips = 0;
    for (int bit = 0; bit < 31; bit++) {
        int abit = (a >> bit) & 1, bbit = (b >> bit) & 1, cbit = (c >> bit) & 1;
        if (cbit == 0) {
