// Each word becomes a 26-bit letter mask; disjoint masks = a valid pair
int maxProduct(vector<string>& words) {
    int n = words.size();
    vector<int> mask(n, 0), len(n, 0);
    for (int i = 0; i < n; i++) {
        len[i] = words[i].size();
        for (char ch : words[i]) mask[i] |= 1 << (ch - 'a');
    }
    int best = 0;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if ((mask[i] & mask[j]) == 0) best = max(best, len[i] * len[j]);
    return best;
}   // O(n^2) time · O(n) space

