            for dr, dc in ((0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    m |= 1 << (nr * cols + nc)     # cell plus its neighbours
            toggles[r * cols + c] = m
    start = 0
    for r in range(rows):
        for c in range(cols):
            if mat[r][c]:
                start |= 1 << (r * cols + c)
    dist = {start: 0}
    queue = deque([start])
    while queue:
        cur = queue.popleft()
        if cur == 0:
            return dist[cur]                # the all-zero board
        for m in toggles:
            nxt = cur ^ m                   # one move
            if nxt not in dist:
                dist[nxt] = dist[cur] + 1
                queue.append(nxt)
    return -1

code.c:
// BFS over bitmask states: from all-zero, flipping a cell flips its neighbours too.
int minFlips(int rows, int cols, int **mat) {
    int total = rows * cols;
    int start = 0;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (mat[r][c]) start |= 1 << (r * cols + c);
    if (!start) return 0;
    int *distance = malloc(sizeof(int) * (size_t) (1 << total));
    for (int i = 0; i < (1 << total); i++) distance[i] = -1;
    int *queue = malloc(sizeof(int) * (size_t) (1 << total));
    int head = 0, tail = 0;
    distance[start] = 0;
    queue[tail++] = start;
    int dr[5] = {0, 1, -1, 0, 0}, dc[5] = {0, 0, 0, 1, -1};
    while (head < tail) {
        int state = queue[head++];
        if (state == 0) {                                   // solved: the state is all zeros
            int answer = distance[state];
            free(distance); free(queue);
            return answer;
        }
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                int next = state;
                for (int k = 0; k < 5; k++) {               // the cell plus its four neighbours
                    int nr = r + dr[k], nc = c + dc[k];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    next ^= 1 << (nr * cols + nc);
                }
                if (distance[next] < 0) {
                    distance[next] = distance[state] + 1;
                    queue[tail++] = next;
                }
            }
    }
    free(distance); free(queue);
    return -1;
}   // O(2^(rows * cols) * rows * cols) time · O(2^(rows * cols)) space

