// Count the sequences starting with 'H' using binomials, and walk the string from the left.
long long binomial(int n, int r) {
    long long result = 1;
    if (r > n - r) r = n - r;
    for (int i = 1; i <= r; i++) {
        result = result * (n - r + i) / i;                  // exact: no overflow for n <= 30
    }
    return result;
}

