long long allOnes(long long base, int digits, long long cap) {
    long long value = 1, term = 1;
    for (int i = 1; i < digits; i++) {
        if (term > cap / base) return cap + 1;          // already too large
        term *= base;
        value += term;
        if (value > cap) return cap + 1;
    }
