def smallest_good_base(n):
    target = int(n)
    best = target - 1                      # n is "11" in base n - 1

    def all_ones(base, digits):
        value = term = 1
        for _ in range(digits - 1):
            term *= base
            value += term
            if value > target:
                return value                   # already past the target
        return value

    for digits in range(3, 63):            # a longer run of 1s needs a smaller base
        lo, hi = 2, target - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            value = all_ones(mid, digits)
            if value == target:
                best = min(best, mid)
                break
            if value > target:
                hi = mid - 1
            else:
                lo = mid + 1
    return str(best)

