int *plusOne(int *digits, int n, int *returnSize) {
    for (int i = n - 1; i >= 0; i--) {
        if (digits[i] < 9) { digits[i]++; *returnSize = n; return digits; }
        digits[i] = 0;                                      // this digit carries
