    int *out = malloc(sizeof(int) * (size_t) (n + 1));
    out[0] = 1;
    for (int i = 0; i < n; i++) out[i + 1] = 0;
    *returnSize = n + 1;
    return out;
}   // O(n) time · O(1) extra space

