// The sequence must fall into the 4-cycle if it is not happy
bool isHappy(int n) {
    unordered_set<int> seen;
    while (n != 1 && !seen.count(n)) {
        seen.insert(n);
        int next = 0;
        while (n > 0) {                       // sum of squared digits
            int digit = n % 10;
            next += digit * digit;
            n /= 10;
        }
        n = next;
    }
    return n == 1;
}   // O(log n) per step · O(1) space (the cycle is tiny)

