// Equal parts are best and 3 is the best size
int integerBreak(int n) {
    if (n <= 3) return n - 1;                 // 2 -> 1, 3 -> 2
    int threes = n / 3, rest = n % 3;
    if (rest == 1) { threes--; rest = 4; }    // 3 + 1 is worse than 2 + 2
    long long best = 1;
    for (int i = 0; i < threes; i++) best *= 3;
    if (rest) best *= rest;
    return (int) best;
}   // O(n) time · O(1) space

