    long long low = 0, high = (long long) sqrt((double) c);
    while (low <= high) {
        long long sum = low * low + high * high;
        if (sum == c) return 1;
        if (sum < c) low++;
        else high--;
    }
    return 0;
}   // O(sqrt(c)) time · O(1) space

