// Long division; a repeated remainder marks the recurring block
string fractionToDecimal(int numerator, int denominator) {
    if (numerator == 0) return "0";
    string result;
    if ((numerator < 0) != (denominator < 0)) result += '-';
    long long top = llabs((long long) numerator), bottom = llabs((long long) denominator);
    result += to_string(top / bottom);                   // integer part
    long long remainder = top % bottom;
    if (remainder == 0) return result;
    result += '.';
    unordered_map<long long, int> seen;                  // remainder -> position
    while (remainder != 0) {
        auto it = seen.find(remainder);
        if (it != seen.end()) {                          // the block repeats from here
            result.insert(it->second, "(");
            result += ')';
            break;
        }
        seen[remainder] = result.size();
        remainder *= 10;
        result += char('0' + remainder / bottom);
        remainder %= bottom;
    }
    return result;
}   // O(denominator) time · O(denominator) space

code.java:
// Long division; a repeated remainder marks the recurring block
String fractionToDecimal(int numerator, int denominator) {
    if (numerator == 0) return "0";
    StringBuilder result = new StringBuilder();
    if ((numerator < 0) != (denominator < 0)) result.append('-');
    long top = Math.abs((long) numerator), bottom = Math.abs((long) denominator);
    result.append(top / bottom);                         // integer part
    long remainder = top % bottom;
    if (remainder == 0) return result.toString();
    result.append('.');
    Map<Long, Integer> seen = new HashMap<>();           // remainder -> position
    while (remainder != 0) {
        Integer at = seen.get(remainder);
        if (at != null) {                                // the block repeats from here
            result.insert(at, "(");
            result.append(')');
            break;
        }
        seen.put(remainder, result.length());
        remainder *= 10;
        result.append((char) ('0' + remainder / bottom));
        remainder %= bottom;
    }
    return result.toString();
}   // O(denominator) time · O(denominator) space

code.c:
// Long division with a "seen remainder → position" table to spot the cycle.
char *fractionToDecimal(long long numerator, long long denominator) {
    if (!numerator) return strdup("0");
    char *out = malloc(8192);
    int length = 0;
    if ((numerator < 0) != (denominator < 0)) out[length++] = '-';
    long long a = llabs(numerator), b = llabs(denominator);
    length += snprintf(out + length, 32, "%lld", a / b);
    long long remainder = a % b;
    if (remainder) {
        out[length++] = '.';
        int *seen = malloc(sizeof(int) * 65536);
        for (int i = 0; i < 65536; i++) seen[i] = -1;
        while (remainder && seen[remainder] < 0) {
            seen[remainder] = length;                       // remember where this remainder started
            remainder *= 10;
            out[length++] = (char) ('0' + remainder / b);
            remainder %= b;
        }
        if (remainder) {                                    // the cycle repeats: wrap it in ()
            int startPosition = seen[remainder];
            for (int i = length; i > startPosition; i--) out[i] = out[i - 1];
            out[startPosition] = '(';
            out[++length] = ')';
            length++;
        }
        free(seen);
    }
    out[length] = '\0';
    return out;
}   // O(denominator) time · O(denominator) space

