// The worst moment is the smallest prefix sum
int minStartValue(vector<int>& nums) {
    int prefix = 0, lowest = 0;
    for (int x : nums) {
        prefix += x;
        lowest = min(lowest, prefix);        // the deepest dip
    }
    return 1 - lowest;                       // lift that dip up to 1
}   // O(n) time · O(1) space

