int minStartValue(const int *nums, int n) {
    int prefix = 0, lowest = 0;
    for (int i = 0; i < n; i++) {
        prefix += nums[i];
        if (prefix < lowest) lowest = prefix;
    }
    return 1 - lowest;
}   // O(n) time · O(1) space

