    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) / 2;
    int count = countReverse(a, lo, mid) + countReverse(a, mid, hi);
    int j = mid;
    for (int i = lo; i < mid; i++) {                         // two pointers over the halves
        while (j < hi && (long long) a[i] > 2LL * a[j]) j++;
        count += j - mid;
