    int i = lo, k = lo;
    j = mid;
    while (i < mid && j < hi) scratchPairs[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < mid) scratchPairs[k++] = a[i++];
    while (j < hi) scratchPairs[k++] = a[j++];
    for (int t = lo; t < hi; t++) a[t] = scratchPairs[t];
    return count;
}

